const operationCapabilities = `-- name: OperationCapabilities :many
SELECT parent_id, position, value FROM cloudformation_operations_capabilities WHERE parent_id = ? ORDER BY position
`

func (q *Queries) OperationCapabilities(ctx context.Context, parentID string) ([]CloudformationOperationsCapability, error) {
	rows, err := q.db.QueryContext(ctx, operationCapabilities, parentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CloudformationOperationsCapability{}
	for rows.Next() {
		var i CloudformationOperationsCapability
		if err := rows.Scan(&i.ParentID, &i.Position, &i.Value); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

